{-# LANGUAGE OverloadedStrings #-}
{-# LANGUAGE TemplateHaskell #-}
-- | Loads the committed WebAuthn fixture corpus
-- (@test\/fixtures\/webauthn\/ceremony.json@) so every crypto test verifies
-- crypton against bytes produced by an independent implementation (Node's
-- WebCrypto / OpenSSL), never against this codebase's own encoder.
--
-- The corpus is regenerated by @scripts\/gen-webauthn-fixture.mjs@; the suite
-- itself never runs Node.
module Seal.Security.WebAuthnSpecFixture
  ( Fixture (..)
  , loadFixture
  , fixtureSignature
  , fixturePublicKey
  , fixtureCredentialId
  ) where

import Data.Aeson (FromJSON (..), eitherDecodeStrict', withObject, (.:))
import Data.ByteString (ByteString)
import Data.ByteString qualified as BS
import Data.ByteString.Base64.URL qualified as B64Url
import Data.Text (Text)
import Data.FileEmbed (embedFile)
import Data.Text.Encoding qualified as TE

import Seal.Security.WebAuthn.Types (CosePublicKey (..))

data Fixture = Fixture
  { fxRpId          :: Text
  , fxOrigin        :: Text
  , fxChallenge     :: Text
  , fxCredentialId  :: ByteString
  , fxPublicKey     :: ByteString
  , fxRegClientData :: ByteString
  , fxAttestation   :: ByteString
  , fxRegAuthData   :: ByteString
  , fxRawId         :: ByteString
  , fxAsnClientData :: ByteString
  , fxAuthData      :: ByteString
  , fxSignature     :: ByteString
  , fxSignCount     :: Int
  } deriving stock (Show)

instance FromJSON Fixture where
  parseJSON = withObject "Fixture" $ \o -> do
    reg <- o .: "registration"
    asn <- o .: "assertion"
    Fixture
      <$> o .: "rp_id"
      <*> o .: "origin"
      <*> o .: "challenge"
      <*> (decodeB64 =<< o .: "credential_id")
      <*> (decodeB64 =<< o .: "public_key")
      <*> (decodeB64 =<< reg .: "client_data_json")
      <*> (decodeB64 =<< reg .: "attestation_object")
      <*> (decodeB64 =<< reg .: "authenticator_data")
      <*> (decodeB64 =<< reg .: "raw_id")
      <*> (decodeB64 =<< asn .: "client_data_json")
      <*> (decodeB64 =<< asn .: "authenticator_data")
      <*> (decodeB64 =<< asn .: "signature")
      <*> asn .: "sign_count"
    where
      decodeB64 raw = case B64Url.decodeUnpadded (TE.encodeUtf8 (raw :: Text)) of
        Left e  -> fail ("fixture: invalid base64url: " <> e)
        Right b -> pure b

-- | The one committed corpus, read once.
loadFixture :: Fixture
loadFixture = case eitherDecodeStrict' fixtureBytes of
  Left e  -> error ("could not decode the embedded WebAuthn fixture: " <> e)
  Right f -> f

-- | The corpus is embedded at build time, so the test is independent of the
-- working directory another spec may have left behind.
fixtureBytes :: BS.ByteString
fixtureBytes = $(embedFile "test/fixtures/webauthn/ceremony.json")

fixtureSignature :: ByteString
fixtureSignature = fxSignature loadFixture

fixturePublicKey :: CosePublicKey
fixturePublicKey = CosePublicKey (fxPublicKey loadFixture)

fixtureCredentialId :: ByteString
fixtureCredentialId = fxCredentialId loadFixture
